write('apps/api/src/policy.ts',`
export const terminalStatuses = ['REJECTED','WITHDRAWN','NOT_SELECTED','JOINED'];
export function canReapply(status:string, closedAt:Date|null, now:Date, wait=30) {
 return terminalStatuses.includes(status) && !!closedAt && now.getTime()-closedAt.getTime() >= wait*86400000;
}
export function contactAllowed(active:boolean, directoryConsent:boolean, applicationConsent:boolean) { return active && (directoryConsent || applicationConsent); }
export function renewalStart(previousEnd:Date|null, now:Date) { return previousEnd && previousEnd > now ? previousEnd : now; }
export function anonymous(candidate:any) { return {id:candidate.id,displayId:candidate.displayId,subject:candidate.subject,qualification:candidate.qualification,experience:candidate.experience,location:candidate.location,salary:candidate.salary,active:candidate.active}; }
`);
write('apps/api/src/policy.test.ts',`
import {test} from 'node:test';
import {strict as assert} from 'node:assert';
import {canReapply,contactAllowed,anonymous,renewalStart} from './policy';
test('private fields never enter anonymous previews',()=>{assert.deepEqual(anonymous({id:'c',displayId:'TC1',subject:'Math',qualification:'BEd',experience:2,location:'Delhi',salary:30000,active:true,mobile:'123',user:{name:'Secret',email:'private'}}),{id:'c',displayId:'TC1',subject:'Math',qualification:'BEd',experience:2,location:'Delhi',salary:30000,active:true});});
test('hidden directory candidate may use application consent, inactive may not',()=>{assert.equal(contactAllowed(true,false,true),true);assert.equal(contactAllowed(false,true,true),false);assert.equal(contactAllowed(true,false,false),false);});
test('reapplication requires terminal state and elapsed closed-at wait',()=>{const now=new Date('2026-10-09');assert.equal(canReapply('REJECTED',new Date('2026-09-09'),now),true);assert.equal(canReapply('APPLIED',new Date('2026-09-01'),now),false);assert.equal(canReapply('WITHDRAWN',new Date('2026-10-01'),now),false);});
test('early renewal queues while expired renewal starts now',()=>{const now=new Date('2026-10-09');assert.equal(renewalStart(new Date('2026-10-15'),now).toISOString(),new Date('2026-10-15').toISOString());assert.equal(renewalStart(new Date('2026-10-01'),now),now);});
`);
